import{_ as t,o,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Module Development — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Module Development — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/module-development-guide"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Module Development — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/module-development-guide"}]]},"headers":[],"relativePath":"developer-guide/module-development-guide.md","filePath":"developer-guide/module-development-guide.md","lastUpdated":1786190008000}'),n={name:"developer-guide/module-development-guide.md"};function d(s,e,r,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="module-development-—-developer-guide" tabindex="-1">Module Development — Developer Guide <a class="header-anchor" href="#module-development-—-developer-guide" aria-label="Permalink to &quot;Module Development — Developer Guide&quot;">​</a></h1><p>Canonical checklist for building a business module. Copy the <strong>Leads</strong> module structure; do not invent a second pattern.</p><h2 id="registration-recipe" tabindex="-1">Registration recipe <a class="header-anchor" href="#registration-recipe" aria-label="Permalink to &quot;Registration recipe&quot;">​</a></h2><ol><li><strong>Catalog (production)</strong> — Ship an idempotent <strong>data migration</strong> that calls <code>App\\Support\\Catalog\\DefaultModuleRegistrar</code> (<code>slug</code>, pricing defaults, <code>status=published</code>, <code>is_default_included</code> / <code>is_billable</code>, optional <code>version</code>). Also keep <code>CatalogSeeder</code> in sync for <strong>local/CI fresh DBs only</strong> — never rely on <code>db:seed</code> in production. Optional: Central Modules API for non-default / commercial catalog edits.</li><li><strong>Permissions (production)</strong> — Add <code>{slug} =&gt; [view, create, update, delete, …]</code> in <code>config/tenant-permissions.php</code> and default grants in <code>config/tenant-default-role-permissions.php</code>. Ship a data migration that calls <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code> so existing workspaces receive grants additively. Modules never auto-grant permissions; roles do. Login never syncs RBAC.</li><li><strong>Routes</strong> — Tenant API:</li></ol><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">middleware</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;auth:tenant-api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tenant.user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;verified&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;module:{slug}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;can:{slug}.view&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><ol start="4"><li><strong>Domain code</strong> — Flat under existing namespaces (no <code>Modules/</code> package):</li></ol><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th></tr></thead><tbody><tr><td>Models</td><td><code>app/Models/</code> + <code>BelongsToTenant</code></td></tr><tr><td>Migrations</td><td><code>database/migrations/</code></td></tr><tr><td>Factories</td><td><code>database/factories/</code></td></tr><tr><td>Seeders</td><td><code>database/seeders/Tenant/</code> for local/demo only; production catalog/permission rows use <strong>data migrations</strong></td></tr><tr><td>Controllers</td><td><code>app/Http/Controllers/Tenant/Api/V1/</code></td></tr><tr><td>Form requests</td><td><code>app/Http/Requests/Tenant/Api/V1/{Module}/</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/{Module}/</code></td></tr><tr><td>Policies</td><td><code>app/Policies/</code></td></tr><tr><td>Services</td><td><code>app/Services/Tenant/</code></td></tr><tr><td>Events / Listeners</td><td><code>app/Events/</code>, <code>app/Listeners/</code></td></tr><tr><td>Notifications</td><td><code>app/Notifications/Tenant/</code></td></tr></tbody></table><ol start="5"><li><strong>Frontend</strong> — <code>src/pages/{slug}/</code>, API service, types, <code>PERMISSIONS</code> / <code>QUERY_KEYS</code>, nav item with <code>permission</code> <strong>and</strong> <code>module</code>, route under <code>TenantProtectedRoute</code>.</li><li><strong>Tests</strong> — Pest feature suite + Playwright <code>test:e2e:{slug}</code>.</li><li><strong>Docs</strong> — User / developer / production guides, API, database, CHANGELOG.</li></ol><h2 id="logging-both-required" tabindex="-1">Logging (both required) <a class="header-anchor" href="#logging-both-required" aria-label="Permalink to &quot;Logging (both required)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Mechanism</th><th>Purpose</th></tr></thead><tbody><tr><td>Audit</td><td><code>PlatformAuditService</code> → <code>activity(&#39;platform&#39;)</code></td><td>Actor, workspace, IP, UA, action for create/update/delete/assign/status changes</td></tr><tr><td>Activity</td><td>Spatie <code>LogsActivity</code> on primary model</td><td>Attribute-level change history</td></tr><tr><td>Timeline</td><td>Domain <code>*_activities</code> table (when UX needs it)</td><td>User-facing history (notes, stage moves, assignments)</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>Dispatch domain events from the service layer. Listeners handle audit side-effects and notifications. Do <strong>not</strong> build per-module notification stacks outside Laravel notifications.</p><h2 id="dashboard-widgets" tabindex="-1">Dashboard widgets <a class="header-anchor" href="#dashboard-widgets" aria-label="Permalink to &quot;Dashboard widgets&quot;">​</a></h2><p>When a module contributes dashboard cards:</p><ol><li>Extend <code>App\\Services\\Tenant\\DashboardWidgetService</code> (same registry pattern as Leads/Tasks).</li><li>Gate each widget on <code>EntitlementService::hasModule</code> + the user’s Spatie permission.</li><li>Apply assignee scoping with <code>ScopesToAssignee</code> when the module uses <code>{slug}.assign</code>.</li><li>Return <code>{ id, module, permission, scope, data }</code> objects only — the SPA renders by <code>id</code>.</li><li>Do not invent a parallel dashboard API; extend <code>DashboardWidgetService</code> (Leads/Tasks/Calendar pattern).</li></ol><p>See <a href="/api/tenant-v1-dashboard">tenant-v1-dashboard.md</a>.</p><h2 id="in-app-notifications" tabindex="-1">In-app notifications <a class="header-anchor" href="#in-app-notifications" aria-label="Permalink to &quot;In-app notifications&quot;">​</a></h2><ul><li>Use Laravel notification channels required by the contract for that event (<code>database</code> plus <code>broadcast</code> for realtime in-app delivery; add <code>mail</code> only when product behavior requires it).</li><li>Implement <code>ShouldQueue</code> and use <code>App\\Notifications\\Concerns\\QueuesOnEmails</code> so jobs land on the dedicated <code>emails</code> queue (<code>php artisan queue:work --queue=emails</code>).</li><li>Persist via the standard <code>notifications</code> table; expose tenant APIs under <code>/notifications*</code> (<a href="/api/tenant-v1-notifications">tenant-v1-notifications.md</a>).</li><li>Register realtime in-app types in the SPA Notification Registry; Echo updates Query caches and polling remains a recovery path.</li><li>Schedule due/overdue fan-out through <code>crm:send-due-notifications</code> rather than ad-hoc cron per module.</li><li><strong>Realtime conversation rooms (Team Chat):</strong> in addition to the existing private user notification channel <code>tenant.{tenantId}.user.{userId}</code>, subscribe members to <code>tenant.{tenantId}.conversation.{conversationId}</code> (authorized by <code>TenantConversationChannel</code> — same tenant + conversation membership). Message / reaction / pin / membership broadcasts use that conversation channel; mention and DM alerts still fan out on the user notification channel.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>If the module needs settings, register keys in <code>SystemSettingDefinitions</code> / <code>TenantSettingDefinitions</code> and resolve Central → Tenant → system. Do not invent a parallel settings store.</p><h2 id="date-and-time-required-for-every-module" tabindex="-1">Date and time (required for every module) <a class="header-anchor" href="#date-and-time-required-for-every-module" aria-label="Permalink to &quot;Date and time (required for every module)&quot;">​</a></h2><p>Applies to <strong>all current and future</strong> tenant modules — same rule as Leads, Tasks, Meetings, Calendar, Attendance, and CRM reminders.</p><ol><li><strong>Single timezone</strong> — Settings → General → Timezone (e.g. <code>Asia/Karachi</code>). Never add <code>{module}_timezone</code> or assume server <code>APP_TIMEZONE</code> / UTC for user-facing clocks.</li><li><strong>Absolute datetimes</strong> (<code>due_at</code>, <code>starts_at</code>, <code>ends_at</code>, <code>remind_at</code>, …) — cast with <code>App\\Casts\\UtcDateTime</code>; serialize with <code>App\\Support\\UtcIso</code>; SPA edit/display via <code>src/lib/datetime.ts</code> + <code>useSettingsStore</code>.</li><li><strong>Wall-clock settings</strong> (<code>H:i</code> office hours, digests, cutoffs) — interpret only in the workspace timezone; document that in the module’s user guide.</li><li><strong>Schedulers / “today” / late gates</strong> — use <code>now($workspaceTimezone)</code> or <code>Carbon::now($timezone)</code> after resolving timezone from <code>TenantSettingService</code>; do not rely on bare <code>now()</code> in long-lived workers.</li><li><strong>Docs</strong> — link <a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a> from the module developer guide when the module has any date/time fields.</li></ol><h2 id="anti-patterns-date-time" tabindex="-1">Anti-patterns (date/time) <a class="header-anchor" href="#anti-patterns-date-time" aria-label="Permalink to &quot;Anti-patterns (date/time)&quot;">​</a></h2><ul><li>Per-module timezone picker that diverges from Settings → General</li><li>Default Eloquent <code>datetime</code> cast on absolute scheduling columns when <code>app.timezone</code> may be non-UTC</li><li>Bare <code>now()</code> / <code>today()</code> in scheduled commands without an explicit workspace timezone</li><li>Showing browser-local times while storing “naive” workspace wall clocks without conversion</li></ul><h2 id="catalog-versioning-modules-version" tabindex="-1">Catalog versioning (<code>modules.version</code>) <a class="header-anchor" href="#catalog-versioning-modules-version" aria-label="Permalink to &quot;Catalog versioning (`modules.version`)&quot;">​</a></h2><p>Marketplace detail shows the catalog <strong>version</strong> string (semver: <code>MAJOR.MINOR.PATCH</code>). It is <strong>display / release metadata</strong> for the central catalog row — not a per-workspace entitlement version, and not a per-workspace code pin.</p><h3 id="semver-policy" tabindex="-1">SemVer policy <a class="header-anchor" href="#semver-policy" aria-label="Permalink to &quot;SemVer policy&quot;">​</a></h3><p>EloSync modules ship <strong>backward-compatible</strong> updates. Do <strong>not</strong> introduce breaking changes to module APIs, permissions contracts, or tenant data semantics. Prefer additive schema, additive API fields, and migrate-forward data migrations.</p><table tabindex="0"><thead><tr><th>Change</th><th>Bump</th><th>Example</th></tr></thead><tbody><tr><td>First ship of a new module</td><td>Start at <strong>1.0.0</strong></td><td>Pass <code>version</code> =&gt; <code>1.0.0</code> into <code>ensureModule</code></td></tr><tr><td>Bug fix, copy, polish, small non-breaking fix</td><td><strong>PATCH</strong></td><td><code>1.0.0</code> → <code>1.0.1</code></td></tr><tr><td>Additive feature, schema, API, or UX (backward compatible)</td><td><strong>MINOR</strong></td><td><code>1.0.1</code> → <code>1.1.0</code></td></tr><tr><td>Large milestone that remains backward compatible (major product surface)</td><td><strong>MAJOR</strong></td><td><code>1.1.0</code> → <code>2.0.0</code></td></tr><tr><td>Docs-only / no catalog-visible product change</td><td>No bump</td><td>—</td></tr></tbody></table><p>Ship every product bump as a data migration that calls <code>DefaultModuleRegistrar::bumpVersion(&#39;{slug}&#39;, &#39;{new}&#39;)</code>.</p><p>Reserve breaking removals / incompatible contract changes — they are <strong>out of policy</strong>. If an exceptional break is ever approved, document it explicitly in the CHANGELOG and treat it as a <strong>MAJOR</strong> bump with a migration / upgrade path.</p><h3 id="who-receives-the-update" tabindex="-1">Who receives the update? <a class="header-anchor" href="#who-receives-the-update" aria-label="Permalink to &quot;Who receives the update?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Code + schema</strong></td><td>One Backend/Frontend deploy. Every workspace runs the same app — there is no per-tenant module code version.</td></tr><tr><td><strong>Catalog <code>version</code> string</strong></td><td>One central <code>modules</code> row. Marketplace shows the same version to every workspace.</td></tr><tr><td><strong>Entitlement (install / enable)</strong></td><td>Unchanged by a version bump. Workspaces that already have the module entitled get the new behavior immediately. Workspaces that never installed (or cancelled / suspended) stay off until they install or re-enable.</td></tr></tbody></table><p>A version bump does <strong>not</strong> auto-install a module for workspaces that have not enabled it.</p><p>Rules agents and developers must follow:</p><ul><li><code>ensureModule</code> uses <code>firstOrCreate</code> by slug — it <strong>does not</strong> update <code>version</code> (or commercial flags) on existing rows. Never expect a re-run of the registrar or <code>CatalogSeeder</code> to bump versions in production.</li><li>Always bump with an explicit idempotent migration: <code>app(DefaultModuleRegistrar::class)-&gt;bumpVersion(&#39;calendar&#39;, &#39;1.1.0&#39;);</code></li><li>Note user-visible bumps in the Docs CHANGELOG (include old → new catalog version).</li><li>Do not invent a parallel versioning system outside <code>modules.version</code>.</li></ul><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><p>Paid modules: catalog <code>is_billable</code>, marketplace install, <code>ModuleSubscriptionService</code>, consolidated billing. Never implement independent payment flows.</p><h2 id="frontend-checklist" tabindex="-1">Frontend checklist <a class="header-anchor" href="#frontend-checklist" aria-label="Permalink to &quot;Frontend checklist&quot;">​</a></h2><ul><li>Pages, forms, tables, filters, dialogs/drawers</li><li>Shared design system (<code>PageHeader</code>, <code>DataTable</code>, <code>PermissionGate</code>, empty/error/loading states)</li><li>Nav + breadcrumbs respect <strong>installed modules</strong> and <strong>user permissions</strong></li><li>Auth payload includes active module slugs for SPA gating</li><li>Module list shortcuts via <code>useModuleShortcuts</code>: bare <code>n</code> (create, permission-gated; Chromium blocks <code>Ctrl/⌘N</code>) and <code>mod+f</code> (focus module <code>SearchInput</code> with <code>ref</code> + <code>shortcutHint</code>). Do <strong>not</strong> bind create/search on the app shell — keep them route-scoped like Leads.</li></ul><h2 id="testing-checklist" tabindex="-1">Testing checklist <a class="header-anchor" href="#testing-checklist" aria-label="Permalink to &quot;Testing checklist&quot;">​</a></h2><p><strong>Pest:</strong> unit where useful; feature CRUD; authorization; validation; tenant isolation; module middleware denial.</p><p><strong>Playwright:</strong> dedicated suite; script <code>test:e2e:{slug}</code>; independently runnable.</p><p><strong>Manual QA:</strong> Cursor browser — CRUD, search, filters, pagination, validation, authz, responsive layout, console, network.</p><h2 id="anti-patterns" tabindex="-1">Anti-patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-patterns&quot;">​</a></h2><ul><li>Laravel Modules / nwidart / plugin discovery</li><li>Repositories layer</li><li>Skipping <code>module:</code> or <code>can:</code> middleware</li><li>Static nav that ignores entitlements</li><li>Custom audit/notification systems outside platform services</li><li>Production <code>db:seed</code> / <code>CatalogSeeder</code> to register default modules</li><li>Login-time or dashboard-time permission “repair”</li><li><code>syncPermissions()</code> on existing customized roles during deploy</li><li>Per-module timezone or server-UTC user clocks (see Date and time above)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/module-architecture">Module Architecture</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a></li><li><a href="/architecture/module-licensing">Module Licensing</a></li><li><a href="/developer-guide/tenant-settings#timezone-and-scheduled-datetimes">Workspace timezone convention</a></li><li><a href="/deployment/module-development">Production module registration</a></li><li><a href="/developer-guide/communication-templates">Communication Templates</a> — reusable platform module pattern</li><li><a href="/developer-guide/tenant-provisioning">Tenant provisioning</a></li></ul>',49)])])}const g=t(n,[["render",d]]);export{u as __pageData,g as default};
